import json,hashlib
D={'pages':[],'units':[],'boundary_notes':[],'review_notes':[],'completed':False};OUT='/workspace/scratch/volume4/batch489-498.json'
def save():json.dump(D,open(OUT,'w'),ensure_ascii=False,indent=2)
def p(n,rows):
 pars=[]
 for i,(ar,ru) in enumerate(rows,1):
  id=f'v4-p{n:03}-{i:02}';pars.append(dict(id=id,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True));D['units'].append(dict(id=id+'-ru',source_ids=[id],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 D['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pars));save()
def merge(a,b):
 x=next(x for x in D['units'] if a in x['source_ids']);y=next(x for x in D['units'] if b in x['source_ids']);x['source_ids']+=y['source_ids'];x['printed_pages']+=y['printed_pages'];x['ar']+=' '+y['ar'];x['ru']+=' '+y['ru'];D['units'].remove(y);save()
p(489,[('لأن المعنى: شهد الله أن الدين عنده الإسلام؛ فلم عدل إلى لفظ الظاهر؟','Ведь смысл таков: «Аллах засвидетельствовал, что религия у Него — ислам». Почему же вместо местоимения употреблено явно выраженное имя?'),('قيل: هذا يرجح قراءة الجمهور وأنها أحسن وأفصح، ولكن يجوز إقامة الظاهر مقام المضمر، وقد ورد في القرآن وكلام العرب كثيرا. قال تعالى: {وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ} [البقرة: 196] وقوله: {وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ} [الأنفال: 69]. وقال تعالى: {وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلَاةَ إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ} [الأعراف: 170].','Ответ: это даёт преимущество чтению большинства и указывает, что оно лучше и красноречивее. Однако употреблять явно выраженное имя вместо местоимения допустимо; это часто встречается в Коране и арабской речи. Всевышний сказал: {وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ} — «Бойтесь Аллаха и знайте, что Аллах суров в наказании» [«Аль-Бакара», 2:196]; {وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ} — «Бойтесь Аллаха: поистине, Аллах — Прощающий, Милосердный» [«Аль-Анфаль», 8:69]; {وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلَاةَ إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ} — «А те, которые крепко держатся Писания и совершают молитву, — Мы не теряем награды исправляющих» [«Аль-Араф», 7:170].'),('قال ابن عباس: افتخر المشركون بآبائهم، فقال كل فريق منهم: لا دين إلا دين آبائنا وما كانوا عليه، فأكذبهم الله تعالى، وقال: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} يعني الذي جاء به محمد، وهو دين الأنبياء من أولهم إلى آخرهم، ليس لله دين سواه، {وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخَاسِرِينَ} [آل عمران: 85].','Ибн Аббас сказал: «Многобожники хвалились своими отцами, и каждая их группа говорила: “Нет иной религии, кроме религии наших отцов и того, чему они следовали”. Всевышний Аллах опроверг их и сказал: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} — “Поистине, религия у Аллаха — ислам” [«Аль Имран», 3:19], то есть тот, с которым пришёл Мухаммад. Это религия пророков от первого до последнего; у Аллаха нет иной религии. {وَمَنْ يَبْتَغِ غَيْرَ الْإِسْلَامِ دِينًا فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخَاسِرِينَ} — “Кто ищет иной религии, кроме ислама, от того это не будет принято, и в Последней жизни он окажется среди потерпевших убыток” [«Аль Имран», 3:85]».'),('وقد دل قوله: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} على أنه دين أنبيائه ورسله وأتباعهم من أولهم إلى آخرهم، ولم يكن لله قط ولا يكون له دين سواه. قال أول الرسل نوح: {فَإِنْ تَوَلَّيْتُمْ فَمَا سَأَلْتُكُمْ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ} [يونس: 72]. وقال إبراهيم وإسماعيل: {رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ} [البقرة: 128]، {وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَى لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ} [البقرة: 132]. وقال يعقوب لبنيه عند الموت: {مَا تَعْبُدُونَ مِنْ','Слова {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} — «Поистине, религия у Аллаха — ислам» [«Аль Имран», 3:19] — указывают, что это религия Его пророков, посланников и их последователей от первого до последнего. У Аллаха никогда не было и не будет иной религии. Первый из посланников, Нух, сказал: {فَإِنْ تَوَلَّيْتُمْ فَمَا سَأَلْتُكُمْ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ} — «Если вы отвернётесь, то я ведь не просил у вас награды. Моя награда — только у Аллаха, и мне велено быть одним из мусульман» [«Юнус», 10:72]. Ибрахим и Исмаил сказали: {رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنَا أُمَّةً مُسْلِمَةً لَكَ} — «Господи наш! Сделай нас двоих покорными Тебе, а из нашего потомства — общину, покорную Тебе» [«Аль-Бакара», 2:128]. {وَوَصَّى بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَى لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ} — «Ибрахим и Якуб завещали это своим сыновьям: “Сыновья мои! Аллах избрал для вас религию; умирайте же только мусульманами”» [«Аль-Бакара», 2:132]. Перед смертью Якуб спросил своих сыновей: {مَا تَعْبُدُونَ مِنْ')])
p(490,[('بَعْدِي قَالُوا نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ} [البقرة: 133]. وقال موسى لقومه: {يَا قَوْمِ إِنْ كُنْتُمْ آمَنْتُمْ بِاللَّهِ فَعَلَيْهِ تَوَكَّلُوا إِنْ كُنْتُمْ مُسْلِمِينَ} [يونس: 84].','بَعْدِي قَالُوا نَعْبُدُ إِلَهَكَ وَإِلَهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ} — «Чему вы будете поклоняться после меня? Они ответили: “Будем поклоняться твоему Богу и Богу твоих отцов Ибрахима, Исмаила и Исхака — Единому Богу, и Ему мы покорны”» [«Аль-Бакара», 2:133]. Муса сказал своему народу: {يَا قَوْمِ إِنْ كُنْتُمْ آمَنْتُمْ بِاللَّهِ فَعَلَيْهِ تَوَكَّلُوا إِنْ كُنْتُمْ مُسْلِمِينَ} — «Народ мой! Если вы уверовали в Аллаха, то на Него и уповайте, если вы мусульмане» [«Юнус», 10:84].'),('وقال تعالى: {فَلَمَّا أَحَسَّ عِيسَى مِنْهُمُ الْكُفْرَ قَالَ مَنْ أَنْصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنْصَارُ اللَّهِ آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ} [آل عمران: 52]، وقالت ملكة سبأ: {رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ} [النمل: 44].','Всевышний сказал: {فَلَمَّا أَحَسَّ عِيسَى مِنْهُمُ الْكُفْرَ قَالَ مَنْ أَنْصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنْصَارُ اللَّهِ آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ} — «Когда Иса почувствовал в них неверие, он сказал: “Кто мои помощники на пути к Аллаху?” Апостолы ответили: “Мы — помощники Аллаха. Мы уверовали в Аллаха; засвидетельствуй, что мы мусульмане”» [«Аль Имран», 3:52]. Царица Сабы сказала: {رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ} — «Господи! Я поступила несправедливо к самой себе и вместе с Сулейманом покорилась Аллаху, Господу миров» [«Ан-Намль», 27:44].'),('فالإسلام دين أهل السماوات ودين أهل التوحيد من أهل الأرض، لا يقبل الله من أحد دينا سواه. فأديان أهل الأرض ستة: واحد للرحمن، وخمسة للشيطان. فدين الرحمن هو الإسلام، والتي للشيطان: اليهودية، والنصرانية، والمجوسية، ودين الصابئة، ودين المشركين.','Итак, ислам — религия обитателей небес и единобожников из обитателей земли. Аллах не принимает ни от кого иной религии. Религий обитателей земли шесть: одна принадлежит Милостивому, а пять — шайтану. Религия Милостивого — ислам; шайтану же принадлежат иудаизм, христианство, религия огнепоклонников, религия сабиев и религия многобожников.'),('فهذا بعض ما تضمنته هذه الآية العظيمة من أسرار التوحيد والمعارف. ولا نستطيل الكلام فيها، فإنه أهم من الكلام على كلام صاحب «المنازل»، فلنرجع إلى شرح كلامه وبيان ما فيه.','Это лишь часть тайн единобожия и познаний, заключённых в этом великом аяте. Не будем затягивать речь о нём, хотя это важнее рассуждения о словах автора «Маназил ас-саирин». Вернёмся же к разъяснению его слов и того, что в них содержится.'),('قال: (وإنما نطق العلماء بما نطقوا به، وأشار المحققون إلى ما أشاروا إليه من هذا الطريق: لقصد تصحيح التوحيد، وما سواه من حال أو مقام فكله مصحوب العلل).','Он сказал: «Учёные произносили то, что произносили, а осуществившие истину указывали на то, на что указывали на этом пути, лишь ради исправления единобожия. Всё же остальное — состояния или стоянки — сопровождается изъянами».'),('يريد: أن التوحيد هو الغاية المطلوبة من جميع المقامات والأعمال','Он имеет в виду, что единобожие — искомая цель всех стоянок, дел')])
p(491,[('والأحوال، فغايتها كلها التوحيد، وإنما كلام العلماء والمحققين من أهل السلوك كله لقصد تصحيحه. وهذا بين من أول المقامات إلى آخرها، فإنها تشير إلى تصحيحه وتجريده.','и состояний. Цель всего этого — единобожие; все слова учёных и осуществивших истину из людей пути направлены лишь на его исправление. Это ясно от первой до последней стоянки: они указывают на исправление и очищение единобожия.'),('قوله: (وما سواه من حال أو مقام فكله مصحوب العلل)، يريد: أن تجريد التوحيد لا علة معه، إذ لو كان معه علة تصحبه لم يجرد. فتجرده ينفي عنه العلل بالكلية بخلاف ما سواه من المقامات والأحوال، فإن العلل تصحبها.','Его слова «Всё же остальное — состояния или стоянки — сопровождается изъянами» означают: очищенному единобожию не сопутствует изъян, ибо, если бы рядом с ним оставался изъян, оно не было бы очищенным. Его очищенность полностью исключает изъяны, тогда как прочим стоянкам и состояниям они сопутствуют.'),('وعندهم أن علل المقامات لا تزول إلا بتجريد التوحيد. مثاله: أن علة مقام التوكل أن يشهد متوكلا ومتوكلا فيه، ومتوكلا عليه، ويشهد نفس توكله. وهذا كله علة في مقام التوكل، فإنه لا يصح له مقامه إلا بأن لا يشهد مع الوكيل الحق الذي يتوكل عليه غيره، ولا يرى توكله سببا لحصول المطلوب، ولا وسيلة إليه.','Они полагают, что изъяны стоянок исчезают лишь при очищении единобожия. Например, изъян стоянки упования — видеть уповающего, то, относительно чего он уповает, Того, на Кого уповает, и само своё упование. Всё это они считают изъяном стоянки упования. По их мнению, эта стоянка будет верной лишь тогда, когда вместе с Истинным Попечителем, на Которого он уповает, человек не созерцает никого иного и не считает своё упование ни причиной достижения искомого, ни средством к нему.'),('وفيه علة أخرى أدق من هذه عند أرباب الفناء، وهي: أن المتوكل قد وكل أمره إلى مولاه، والتجأ إلى كفايته وتدبيره له والقيام بمصالحه.','У людей фана есть ещё более тонкий изъян упования: уповающий поручает своё дело Владыке, прибегая к тому, что Он обеспечит его, распорядится его делами и позаботится о его благе.'),('قالوا: وهذا في طريق الخاصة عمى عن التوحيد، ورجوع إلى الأسباب؛','Они говорят: «На пути избранных это слепота к единобожию и возвращение к причинам,')])
p(492,[('لأن الموحد قد رفض الأسباب، ووقف مع المسبب وحده؛ والمتوكل وإن رفض الأسباب فإنه واقف مع توكله، فصار توكله بدلا من تلك الأسباب التي رفضها، فهو متعلق بما رفضه.','ведь единобожник отверг причины и остановился на одном лишь Том, Кто их устанавливает. Уповающий же, даже отвергнув причины, останавливается на собственном уповании. Поэтому его упование заменяет отвергнутые причины, и он остаётся привязанным к тому, что отверг».'),('وتجريد التوكل عندهم وحقيقته هو: تخليص القلب من علة التوكل، وهو أن يعلم أن الله سبحانه فرغ من الأشياء وقدرها، وهو سبحانه يسوق المقادير إلى المواقيت. فالمتوكل حقيقة — عندهم — هو من أراح نفسه من كد النظر ومطالعة السبب سكونا إلى ما سبق له من القسم، مع استواء الحالتين عنده، وهو أن يعلم أن الطلب لا ينفع، والتوكل لا يجمع. ومتى طالع بتوكله عوضا كان توكله مدخولا، وقصده معلولا. فإذا خلص من رق هذه الأسباب ومطالعة العوض، ولم يلاحظ في توكله سوى خالص حق الرب سبحانه، كفاه الله تعالى كل مهم، كما أوحى إلى موسى: كن لي كما أريد، أكن لك كما تريد.','Очищение упования и его подлинная суть, по их мнению, — освобождение сердца от изъяна упования: человек знает, что Пречистый Аллах уже завершил определение вещей и предопределил их и что Он ведёт предопределённое к назначенным срокам. Подлинно уповающий, по их мнению, — тот, кто избавил себя от утомительных размышлений и наблюдения за причинами, успокоившись на заранее отведённой ему доле. Оба положения для него равны, поскольку он знает, что поиск не приносит пользы, а упование ничего не собирает. Когда же в своём уповании он ожидает возмещения, его упование оказывается с примесью, а намерение — с изъяном. Если же он освободится от порабощения этими причинами и ожидания возмещения и будет учитывать в своём уповании лишь чистое право Пречистого Господа, Всевышний Аллах избавит его от всякой заботы, как Он внушил Мусе: «Будь для Меня таким, каким Я желаю, и Я буду для тебя таким, каким желаешь ты».'),('وهذا الكلام وأمثاله بعضه صواب، وبعضه خطأ، وبعضه محتمل.','В этих и подобных словах часть верна, часть ошибочна, а часть допускает разные толкования.')])
p(493,[('فقولهم: «إن التوكل في طريق الخاصة عمى عن التوحيد، ورجوع إلى الأسباب» خطأ محض، بل التوكل حقيقة التوحيد، ولا يتم التوحيد إلا به. وقد تقدم في باب التوكل بيان ذلك وأنه من مقامات الرسل، وهم خاصة الخاصة، وإنما المتحذلقون المتنطعون جعلوه من مقامات العامة، ولا أخص من رسل الله، ولا أعلى من مقاماتهم.','Их слова «На пути избранных упование — слепота к единобожию и возвращение к причинам» — чистая ошибка. Напротив, упование — подлинная суть единобожия, и единобожие не достигает полноты без него. В главе об уповании уже было разъяснено это и то, что оно относится к стоянкам посланников, а они — избраннейшие из избранных. Лишь мнящие себя знатоками, чрезмерно изощряющиеся люди сделали его стоянкой простых людей. Но нет никого избраннее посланников Аллаха и нет стоянок выше их стоянок.'),('وقولهم: «إنه رجوع إلى الأسباب»، يقال: بل هو قيام بحق الأمر، فإن الله سبحانه اقتضت حكمته ربط المسببات بأسبابها، وجعل التوكل والدعاء من أقرب الأسباب التي تحصل المقصود. فالتوكل امتثال لأمر الله، وموافقة لحكمته، وعبودية للقلب، فكيف يكون مصحوب العلل؟ وكيف يكون من مقامات العامة؟','На их слова «Это возвращение к причинам» отвечают: напротив, это исполнение того, чего требует повеление. По Своей мудрости Пречистый Аллах связал следствия с их причинами и сделал упование и мольбу одними из ближайших причин достижения цели. Упование — исполнение повеления Аллаха, соответствие Его мудрости и поклонение сердца. Как же оно может сопровождаться изъянами? Как оно может быть лишь стоянкой простых людей?'),('وقوله: «لأن الموحد قد رفض الأسباب كلها»، يقال له: هذا الرفض لا يخرج عن الكفر تارة، والفسق تارة، والتقصير تارة؛ فإن الله أمر بالقيام بالأسباب، فإذا رفض ما أمره الله أن يقوم به فقد ضاد الله في أمره، وكيف يحل لمسلم أن يرفض الأسباب كلها؟','На его слова «Ведь единобожник отверг все причины» следует ответить: такое отвержение в одних случаях является неверием, в других — нечестием, а в третьих — упущением. Аллах велел прибегать к причинам; отвергающий то, к чему Аллах велел прибегать, противится Его повелению. Как мусульманину может быть дозволено отвергнуть все причины?'),('فإن قلت: ليس المراد رفض القيام بها، وإنما المراد: رفض الوقوف معها.','Если ты скажешь: «Подразумевается отказ не от пользования причинами, а от остановки при них», '),('قلت: وهذا أيضا غير مستقيم، فإن الوقوف مع الأسباب قسمان: وقوف مأمور به مطلوب، وهو أن يقف معها حيث أوقفه الله ورسوله، فلا يتعدى حدودها ولا يقصر عنها، فيقف مع مراعاة حدودها وأوقاتها','то я отвечу: и это неверно. Остановка при причинах бывает двух видов. Первый — предписанная и требуемая: человек останавливается при них там, где его остановили Аллах и Его Посланник, не переступая их границ и не допуская упущений. Он соблюдает их границы и сроки')])
merge('v4-p489-04','v4-p490-01');merge('v4-p490-06','v4-p491-01');merge('v4-p491-05','v4-p492-01')
p(494,[('وشرائطها. وهذا الوقوف لا تتم العبودية إلا به.','и условия. Без такой остановки рабское служение не достигает полноты.'),('ووقوف معها، بحيث يعتقد أنها هي الفاعلة المؤثرة بنفسها، وأنها تنفع وتضر بذاتها، فهذا لا يعتقده موحد، ولا يحتاج أن يحترز منه من يتكلم في المعرفة والسلوك.','Второй вид — остановка при причинах с убеждением, что именно они действуют и воздействуют самостоятельно, сами по себе приносят пользу и вред. Единобожник в это не верит, и рассуждающему о познании и духовном пути нет нужды предостерегаться от этого.'),('نعم، لا ينقطع بها عن رؤية المسبب، ويعتقدها هي الغاية المطلوبة منه، بل هي وسيلة توصل إلى الغاية، ولا تصل إلى الغاية المطلوبة بدونها. فهذا حق، لكن: لا يجامع رفضها والإعراض عنها، بل يقوم بها معتقدا أنها وسيلة موصلة إلى الغاية. فهي كالطريق الحسي الذي يقطعه المسافر إلى مقصده، فإن قيل له: ارفض الطريق ولا تلتفت إليها انقطع عن المسير بالكلية. وإن جعلها غايته ولم يقصد بالسير فيها وصوله إلى مقصد معين كان معرضا عن الغاية، مشتغلا بالطريق. وإن قيل له: التفت إلى طريقك ومنازل سيرك، وراعها، وسر فيها ناظرا إلى المقصود، عاملا على الوصول إليه= فهذا هو الحق.','Да, причины не должны отвлекать от созерцания Того, Кто их устанавливает, и человек не должен считать их искомой целью: они — средство, ведущее к цели, без которого искомой цели не достичь. Это верно, но несовместимо с отвержением причин и отворачиванием от них. Напротив, он пользуется ими, считая их средством достижения цели. Они подобны зримой дороге, по которой путник идёт к своей цели. Если ему скажут: «Отвергни дорогу и не обращай на неё внимания», он совсем перестанет двигаться. Если же он сделает саму дорогу целью и не будет стремиться, идя по ней, достичь определённого места, он отвернётся от цели и займётся дорогой. Верно же сказать ему: «Обращай внимание на свою дорогу и места остановок, заботься о них и иди по ней, взирая на цель и трудясь ради её достижения».'),('وقولهم: «المتوكل وإن رفض الأسباب واقف مع توكله». فيقال: إن وقف مع توكله امتثالا لأمر الله، وأداء لحق عبوديته، معتقدا أن الله هو الذي من عليه بالتوكل، وأقامه فيه، وجعله سببا موصلا له إلى مطلوبه، فنعم الوقوف وقف! وما أحسنه من وقوف! وإن وقف معه اعتقادا أن بنفس توكله وعمله يصل، مع قطع النظر عن فضل ربه وإعانته ومنه عليه بالتوكل؛','На их слова «Уповающий, даже отвергнув причины, останавливается при своём уповании» следует ответить: если он останавливается при уповании, исполняя повеление Аллаха и право рабского служения Ему, убеждённый, что именно Аллах одарил его упованием, утвердил его в нём и сделал его причиной достижения искомого, то как прекрасна эта остановка! Как она хороша! Если же он останавливается при нём, полагая, что достигнет цели самим своим упованием и действием, не учитывая милость Господа, Его помощь и то, что Он одарил его упованием,')])
p(495,[('فهو وقوف منقطع عن الله.','то такая остановка отдаляет от Аллаха.'),('وقولهم: «إن التوكل بدل من الأسباب التي رفضها، فالمتوكل متنقل من سبب إلى سبب»، يقال لهم: إن كانت الأسباب التي رفضها غير مأمور بها، فالتوكل المجرد خير منها، وإن كانت مأمورا بها، فرفضه لها إلى التوكل معصية وخروج عن الأمر.','На их слова «Упование заменяет отвергнутые причины, так что уповающий переходит от одной причины к другой» отвечают: если отвергнутые причины не были предписаны, то чистое упование лучше их; если же они были предписаны, то отказ от них ради упования — ослушание и отступление от повеления.'),('نعم، للتوكل ثلاث علل:','Да, у упования есть три изъяна:'),('أحدها: أن يترك به ما أمر به من الأسباب استغناء بالتوكل عنها. فهذا توكل عجز وتفريط وإضاعة، لا توكل عبودية وتوحيد؛ كمن يترك الأعمال التي هي سبب النجاة ويتوكل في حصولها، ويترك القيام بأسباب الرزق من العمل والحراثة والتجارة ونحوها ويتوكل في حصوله؛ ويترك طلب العلم ويتوكل في حصوله= فهذا توكله عجز وتفريط، كما قال بعض السلف: لا تكن ممن يجعل توكله عجزا، وعجزه توكلا.','Первый: человек из-за упования оставляет предписанные ему причины, считая, что упование позволяет обойтись без них. Это упование бессилия, упущения и небрежности, а не рабского служения и единобожия. Таков тот, кто оставляет дела, являющиеся причиной спасения, и уповает на его достижение; оставляет причины получения удела — труд, земледелие, торговлю и тому подобное — и уповает на его получение; оставляет поиск знания и уповает на его обретение. Его упование — бессилие и упущение. Один из предшественников сказал: «Не будь тем, кто превращает упование в бессилие, а бессилие — в упование».'),('العلة الثانية: أن يتوكل في حظوظه وشهواته دون حقوق ربه، كمن يتوكل في حصول مال أو زوجة أو رياسة. وأما التوكل في نصرة دين الله وإعلاء كلماته، وإظهار سنة رسوله، وجهاد أعدائه، فليس فيه علة، بل هو مزيل للعلل.','Второй изъян: упование ради своей доли и страстей, а не ради прав Господа, как у того, кто уповает на получение богатства, жены или власти. Упование же ради помощи религии Аллаха, возвышения Его слов, утверждения сунны Его Посланника и борьбы с Его врагами не содержит изъяна — напротив, устраняет изъяны.'),('العلة الثالثة: أن يرى توكله منه، ويغيب بذلك عن مطالعة المنة وشهود الفضل، وإقامة الله له في مقام التوكل. وليس مجرد رؤية التوكل علة كما يظنه','Третий изъян: считать своё упование исходящим от себя и потому переставать замечать дарованную милость, созерцать благодать и то, что Аллах поставил его на стоянку упования. Однако само по себе видение своего упования не является изъяном, как полагают')])
p(496,[('كثير من الناس، بل رؤية التوكل وأنه من عين الجود ومحض المنة ومجرد التوفيق عبودية، وهي أكمل من كونه يغيب عنه ولا يراه. فالأكمل أن لا يغيب بفضل ربه عنه، ولا به عن شهود فضله، كما تقدم بيانه.','многие люди. Напротив, видеть своё упование и понимать, что оно исходит из самой щедрости Аллаха, чистого дара и одного лишь содействия, — рабское служение. Это совершеннее, чем перестать замечать упование и не видеть его. Совершеннее всего — чтобы ни милость Господа не отвлекала от видения упования, ни само упование — от созерцания Его милости, как уже разъяснялось.'),('فهذه العلل الثلاث هي التي تعرض في مقام التوكل وغيره من المقامات، وهي التي يعمل العارفون بالله وأمره على قطعها. وهكذا الكلام في سائر علل المقامات، وإنما ذكرنا هذا مثالا لما يذكر من عللها. وقد أفرد لها صاحب «المنازل» مصنفا لطيفا، وجعل غالبها معلولا. والصواب: أن عللها هذه الثلاثة المذكورة: أن يترك بها ما هو أعلى منها، وأن يعلقها بحظه والانقطاع بها عن المقصود، وأن لا يراها من عين المنة ومحض الجود. وبالله التوفيق.','Именно эти три изъяна возникают на стоянке упования и других стоянках; над их устранением и трудятся познавшие Аллаха и Его повеление. То же относится к остальным изъянам стоянок; мы привели это лишь как пример обсуждаемых изъянов. Автор «Маназил ас-саирин» посвятил им небольшую отдельную книгу, сочтя большинство стоянок имеющими изъяны. Верно же, что их изъяны — три названных: из-за них оставляют то, что выше их; связывают их со своей долей и из-за них отдаляются от Цели; не видят в них самого дара и чистой щедрости Аллаха. Успех дарует Аллах.'),('قوله: (والتوحيد على ثلاثة أوجه: الوجه الأول: توحيد العامة، الذي يصح بالشواهد. والوجه الثاني: توحيد الخاصة، وهو الذي يثبت بالحقائق. والوجه الثالث: توحيد قائم بالقدم، وهو توحيد خاصة الخاصة).','Его слова: «Единобожие имеет три вида. Первый — единобожие обычных верующих, подтверждаемое свидетельствами. Второй — единобожие избранных, утверждаемое подлинными истинами. Третий — единобожие, пребывающее в предвечности; это единобожие избраннейших из избранных».'),('فيقال: لا ريب أن أهل التوحيد متفاوتون في توحيدهم — علما ومعرفة وحالا — تفاوتا لا يحصيه إلا الله. فأكمل الناس توحيدا: الأنبياء صلوات الله وسلامه عليهم، والمرسلون منهم أكمل في ذلك، وأولو العزم من الرسل أكملهم توحيدا، وهم نوح، وإبراهيم، وموسى، ومحمد صلوات الله وسلامه عليهم. وأكملهم توحيدا: الخليلان محمد وإبراهيم صلوات الله وسلامه','Ответим: нет сомнения, что единобожники различаются в единобожии — в знании, познании и состоянии — так, что только Аллах может исчислить эти различия. Совершеннее всех в единобожии пророки, да благословит их Аллах и приветствует; посланники из их числа ещё совершеннее в этом, а обладающие твёрдой решимостью среди посланников совершеннее всех их в единобожии. Это Нух, Ибрахим, Муса и Мухаммад, да благословит их Аллах и приветствует. Совершеннее же всех в единобожии два особых друга Аллаха — Мухаммад и Ибрахим, да благословит их Аллах и')])
p(497,[('عليهما، فإنهما قاما من التوحيد بما لم يقم به غيرهما علما ومعرفة وحالا، ودعوة للخلق وجهادا. فلا توحيد أكمل من الذي قامت به الرسل، ودعوا إليه، وجاهدوا الأمم عليه.','приветствует: они осуществили единобожие так, как не осуществил никто иной, — в знании, познании, состоянии, призыве к творениям и борьбе. Нет единобожия совершеннее того, которое осуществили посланники, к которому они призывали и за которое боролись с народами.'),('ولهذا أمر الله سبحانه نبيه صلى الله عليه وسلم أن يقتدي بهم فيه، كما قال سبحانه بعد ذكر إبراهيم ومناظرته قومه في بطلان الشرك وصحة التوحيد، وذكر الأنبياء من ذريته، ثم قال: {أُولَئِكَ الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ فَإِنْ يَكْفُرْ بِهَا هَؤُلَاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَيْسُوا بِهَا بِكَافِرِينَ أُولَئِكَ الَّذِينَ هَدَى اللَّهُ فَبِهُدَاهُمُ اقْتَدِهْ} [الأنعام: 89]. فلا أكمل من توحيد من أمر رسول الله صلى الله عليه وسلم أن يقتدي بهم.','Поэтому Пречистый Аллах велел Своему Пророку, да благословит его Аллах и приветствует, следовать их примеру в единобожии. Упомянув Ибрахима и его спор с народом о несостоятельности многобожия и истинности единобожия, а также пророков из его потомства, Пречистый сказал: {أُولَئِكَ الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ فَإِنْ يَكْفُرْ بِهَا هَؤُلَاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَيْسُوا بِهَا بِكَافِرِينَ أُولَئِكَ الَّذِينَ هَدَى اللَّهُ فَبِهُدَاهُمُ اقْتَدِهْ} — «Это те, кому Мы даровали Писание, суждение и пророчество. Если эти не уверуют в это, то Мы уже поручили это людям, которые не отрицают этого. Это те, кого Аллах повёл верным путём. Следуй же их руководству» [«Аль-Анам», 6:89–90]. Нет единобожия совершеннее единобожия тех, чьему примеру велено следовать Посланнику Аллаха, да благословит его Аллах и приветствует.'),('ولما قاموا بحقيقة التوحيد علما وعملا ودعوة وجهادا جعلهم الله أئمة للخلائق، يهدون بأمره، ويدعون إليه. وجعل الخلائق تبعا لهم، يأتمرون بأمرهم، وينتهون إلى ما وقفوا بهم عنده، وخص بالسعادة والفلاح والهدى أتباعهم، وبالشقاء والضلال مخالفيهم؛ وقال لإمامهم وشيخهم إبراهيم خليله: {إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِنْ ذُرِّيَّتِي قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ} [البقرة: 124]، أي لا ينال عهدي بالإمامة مشركا.','Когда они осуществили подлинное единобожие знанием, делом, призывом и борьбой, Аллах сделал их наставниками творений, которые ведут по Его повелению и призывают к Нему. Он сделал творения их последователями, исполняющими их веления и останавливающимися на том, на чём они их остановили. Их последователей Он особо наделил счастьем, успехом и верным руководством, а противящихся им — несчастьем и заблуждением. Их предводителю и старшему, Своему особому другу Ибрахиму, Он сказал: {إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِنْ ذُرِّيَّتِي قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ} — «Я сделаю тебя наставником для людей. Он сказал: “И из моего потомства?” Он сказал: “Мой завет не распространяется на несправедливых”» [«Аль-Бакара», 2:124]. То есть Мой завет о предводительстве не распространяется на многобожника.'),('ولهذا أوصى نبيه محمدا صلى الله عليه وسلم أن يتبع ملة إبراهيم. وكان يعلم أصحابه إذا أصبحوا أن يقولوا: «أصبحنا على فطرة الإسلام، وكلمة الإخلاص، ودين نبينا محمد، وملة أبينا إبراهيم حنيفا مسلما وما كان من المشركين»، فملة','Поэтому Он заповедал Своему Пророку Мухаммаду, да благословит его Аллах и приветствует, следовать вере Ибрахима. Пророк учил сподвижников по утрам говорить: «Мы встретили утро на естественной основе ислама, на слове искренности, на религии нашего Пророка Мухаммада и на вере нашего отца Ибрахима — ханифа, мусульманина, который не был из многобожников». Итак, вера')])
p(498,[('إبراهيم: التوحيد. ودين محمد: ما جاء به من عند الله قولا وعملا واعتقادا. وكلمة الإخلاص هي شهادة أن لا إله إلا الله. وفطرة الإسلام هي ما فطر الله عليه عباده من محبته وعبادته وحده لا شريك له، والاستسلام له عبودية وذلا وانقيادا وإنابة.','Ибрахима — единобожие; религия Мухаммада — то, что он принёс от Аллаха в словах, делах и убеждениях; слово искренности — свидетельство, что нет божества, кроме Аллаха. Естественная основа ислама — то, с чем Аллах создал Своих рабов: любовь к Нему, поклонение Ему одному, без сотоварища, и покорность Ему в рабском служении, смирении, подчинении и обращении к Нему.'),('فهذا هو توحيد خاصة الخاصة، الذي من رغب عنه فهو من أسفه السفهاء.','Вот единобожие избраннейших из избранных. Кто отворачивается от него, тот из самых глупых глупцов.'),('قال تعالى: {وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ إِلَّا مَنْ سَفِهَ نَفْسَهُ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ} [البقرة: 130–131]. فقسم التوحيد الخلائق قسمين: سفيها لا أسفه منه، ورشيدا. فالسفيه: من رغب عنه إلى الإشراك. والرشيد: من تبرأ من الشرك قولا وعملا وحالا، فكان قوله توحيدا، وعمله توحيدا، وحاله توحيدا، ودعوته إلى التوحيد.','Всевышний сказал: {وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ إِلَّا مَنْ سَفِهَ نَفْسَهُ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ} — «Кто же отвернётся от веры Ибрахима, кроме того, кто сделал глупцом самого себя? Мы избрали его в этом мире, а в Последней жизни он — среди праведников. Его Господь сказал ему: “Покорись!” Он сказал: “Я покорился Господу миров”» [«Аль-Бакара», 2:130–131]. Единобожие разделило творения на два вида: глупца, глупее которого никого нет, и благоразумного. Глупец — тот, кто отвернулся от единобожия к приобщению сотоварищей. Благоразумный — тот, кто отрёкся от многобожия словом, делом и состоянием, так что его слова — единобожие, его дела — единобожие, его состояние — единобожие и его призыв — к единобожию.'),('وبهذا أمر الله سبحانه جميع المرسلين من أولهم إلى آخرهم. قال تعالى: {يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ وَإِنَّ هَذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً وَأَنَا رَبُّكُمْ فَاتَّقُونِ} [المؤمنون: 51–52].','Именно это Пречистый Аллах велел всем посланникам от первого до последнего. Всевышний сказал: {يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ وَإِنَّ هَذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً وَأَنَا رَبُّكُمْ فَاتَّقُونِ} — «Посланники! Ешьте благое и совершайте праведные дела. Я знаю то, что вы делаете. Поистине, эта ваша община — единая община, и Я — ваш Господь. Бойтесь же Меня» [«Аль-Муминун», 23:51–52].')])
merge('v4-p493-05','v4-p494-01');merge('v4-p494-04','v4-p495-01');merge('v4-p495-06','v4-p496-01');merge('v4-p496-04','v4-p497-01');merge('v4-p497-04','v4-p498-01')
D['boundary_notes']=[{'printed_page':489,'position':'start','source_id':'v4-p489-01','continuation_of_page':488,'note':'489-01 «لأن المعنى...» продолжает вопрос последнего абзаца488 «فإن قيل: فكان ينبغي على هذه القراءة أن يقول...».488 реально просмотрена для контекста; её текст не импортирован. Требуется внешнее объединение.'},{'printed_page':498,'position':'end','note':'Последний абзац498 завершён;499 реально просмотрена для контекста, начинается самостоятельный абзац «وقال تعالى». Внешнее слияние не требуется.'}];save()
